def transform(grid):
    """Translate all non-background content down by one row."""
    if not grid:
        return []
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    h, w = len(grid), len(grid[0])
    out = [[bg] * w for _ in range(h)]
    for r in range(h - 1):
        for c in range(w):
            if grid[r][c] != bg:
                out[r + 1][c] = grid[r][c]
